// The committed seed (data/seed/exercises.json), generated by scripts/build-seed.mjs from the
// owner's library (GYM-149). These checks are what the app relies on when it seeds or upgrades.
import {
  EQUIPMENT,
  LEVELS,
  MECHANICS,
  MUSCLES,
  PATTERNS,
  subcategoryFits,
  TRAINING_TYPES,
} from '../../domain/catalogue';
import { foldName } from '../exercises';
import { SEED_EXERCISES, SEED_VERSION } from '../seed/exercises';
import { V1_SEED_NAMES } from '../testing/exercisesV1';

test('831 exercises, split by pattern as in the owner library', () => {
  expect(SEED_VERSION).toBe(2);
  expect(SEED_EXERCISES).toHaveLength(831);
  const count = (p: string | null) => SEED_EXERCISES.filter((e) => e.pattern === p).length;
  expect([count('KD'), count('HD'), count('Push'), count('Pull'), count('Core')]).toEqual([
    160, 106, 251, 203, 95,
  ]);
  expect(count(null)).toBe(16);
});

test('every value is one of the fixed lists', () => {
  for (const e of SEED_EXERCISES) {
    if (e.pattern !== null) expect(PATTERNS).toContain(e.pattern);
    expect(subcategoryFits(e.pattern, e.subcategory)).toBe(true);
    expect(TRAINING_TYPES).toContain(e.trainingType);
    expect(EQUIPMENT).toContain(e.equipment);
    if (e.level !== null) expect(LEVELS).toContain(e.level);
    if (e.mechanic !== null) expect(MECHANICS).toContain(e.mechanic);
    for (const m of [...e.primaryMuscles, ...e.secondaryMuscles]) expect(MUSCLES).toContain(m);
    expect([1, 2, 3, 4]).toContain(e.importance);
  }
});

test('cardio, and only cardio, has no pattern', () => {
  for (const e of SEED_EXERCISES) {
    expect(e.pattern === null).toBe(e.trainingType === 'Cardio');
  }
});

test('every exercise has a Polish name and a primary muscle; no muscle has two roles', () => {
  for (const e of SEED_EXERCISES) {
    expect(e.namePl.trim()).not.toBe('');
    expect(e.primaryMuscles.length).toBeGreaterThan(0);
    expect(e.primaryMuscles.filter((m) => e.secondaryMuscles.includes(m))).toEqual([]);
  }
});

test('English names and aliases are all different, ignoring case', () => {
  const names = SEED_EXERCISES.flatMap((e) => [e.nameEn, ...e.aliases]).map(foldName);
  expect(new Set(names).size).toBe(names.length);
});

test('every old library name but the removed hip flexor finds exactly one exercise', () => {
  const hits = (name: string) =>
    SEED_EXERCISES.filter((e) =>
      [e.nameEn, ...e.aliases].some((n) => foldName(n) === foldName(name)),
    ).length;
  for (const name of V1_SEED_NAMES) {
    expect({ name, hits: hits(name) }).toEqual({
      name,
      hits: name === 'Hip flexor variation with locked leg' ? 0 : 1,
    });
  }
});
